+fn msg_cid_images(bytes: &[u8]) -> HashMap<String, PictureImage> {
+    let mut out = HashMap::new();
+    for att in super::msg::attachments(bytes).unwrap_or_default() {
+        let (Some(id), Some(payload)) = (att.content_id.as_deref(), att.payload) else {
+            continue;
